/**
 * Seed Payload CMS D1 database directly via SQL (bypasses REST API — much faster).
 *
 * Reads seed/employees-seed.json (generated by seed/generate.ts) and bulk-inserts
 * departments, regions, and employees into the Payload D1 database using
 * `wrangler d1 execute --remote`.
 *
 * SQL is split into ~5k-employee chunks so each file stays well under D1's limits.
 *
 * Usage:
 *   # 1. Generate seed data first (if not already done)
 *   npx tsx seed/generate.ts
 *
 *   # 2. Run this seeder (requires wrangler auth: pnpm wrangler login)
 *   npx tsx seed/seed-payload.ts
 *
 *   # Dry-run: print SQL without executing
 *   npx tsx seed/seed-payload.ts --dry-run
 *
 * Schema sourced from: src/migrations/20261123_191629.ts
 *   departments: id, name, description, icon, color, updated_at, created_at
 *   regions:     id, name, display_name, timezone, flag_emoji, updated_at, created_at
 *   employees:   id, first_name, last_name, department_id, job_title, region_id,
 *                email, phone, avatar_seed, updated_at, created_at
 */

import fs from 'fs'
import path from 'path'
import { execSync } from 'child_process'
import { fileURLToPath } from 'url'
import type { DEPARTMENTS, REGIONS, EmployeeSeedRecord } from './generate.ts'

const __dirname = path.dirname(fileURLToPath(import.meta.url))
const DRY_RUN = process.argv.includes('--dry-run')

// D1 database name as configured in wrangler.jsonc
const DB_NAME = 'payload-sonicjs'
// Rows per INSERT statement (500 is a safe sweet spot for D1)
const ROWS_PER_INSERT = 50
// Employees per SQL chunk file (~1 MB each at 500 rows/insert)
const EMPLOYEES_PER_CHUNK = 5_000

// ── Helpers ───────────────────────────────────────────────────────────────────

function esc(s: string | number): string {
  return String(s).replace(/'/g, "''")
}

const NOW = `strftime('%Y-%m-%dT%H:%M:%fZ', 'now')`

function runSqlFile(filePath: string, label: string): void {
  if (DRY_RUN) {
    console.log(`  [dry-run] would execute: wrangler d1 execute ${DB_NAME} --remote --file=${filePath}`)
    return
  }
  console.log(`  Executing ${label}…`)
  execSync(`pnpm wrangler d1 execute ${DB_NAME} --remote --file="${filePath}"`, {
    stdio: 'inherit',
    cwd: path.join(__dirname, '..'),
  })
}

// ── SQL builders ──────────────────────────────────────────────────────────────

function buildDeptRegionSql(
  departments: typeof DEPARTMENTS,
  regions: typeof REGIONS,
): string {
  const lines: string[] = [
    '-- Payload seed: departments + regions',
    'PRAGMA foreign_keys=OFF;',
    '',
    '-- Wipe existing data',
    'DELETE FROM employees;',
    'DELETE FROM regions;',
    'DELETE FROM departments;',
    '',
    '-- Departments',
  ]

  for (let i = 0; i < departments.length; i++) {
    const d = departments[i]!
    lines.push(
      `INSERT INTO departments (id, name, description, icon, color, updated_at, created_at) VALUES ` +
      `(${i + 1}, '${esc(d.name)}', '${esc(d.description)}', '${esc(d.icon)}', '${esc(d.color)}', ${NOW}, ${NOW});`,
    )
  }

  lines.push('', '-- Regions')
  for (let i = 0; i < regions.length; i++) {
    const r = regions[i]!
    lines.push(
      `INSERT INTO regions (id, name, display_name, timezone, flag_emoji, updated_at, created_at) VALUES ` +
      `(${i + 1}, '${esc(r.name)}', '${esc(r.display_name)}', '${esc(r.timezone)}', '${esc(r.flag_emoji)}', ${NOW}, ${NOW});`,
    )
  }

  lines.push('', 'PRAGMA foreign_keys=ON;')
  return lines.join('\n')
}

function buildEmployeeChunkSql(
  chunk: EmployeeSeedRecord[],
  deptIndex: Record<string, number>,
  regionIndex: Record<string, number>,
  chunkNum: number,
  totalChunks: number,
): string {
  const lines: string[] = [
    `-- Payload seed: employees chunk ${chunkNum}/${totalChunks} (${chunk[0]!.index}–${chunk[chunk.length - 1]!.index})`,
    'PRAGMA foreign_keys=OFF;',
    '',
  ]

  for (let i = 0; i < chunk.length; i += ROWS_PER_INSERT) {
    const batch = chunk.slice(i, i + ROWS_PER_INSERT)
    const vals = batch.map(emp => {
      const dId = deptIndex[emp.department_slug]!
      const rId = regionIndex[emp.region_slug]!
      return (
        `(${emp.index}, '${esc(emp.first_name)}', '${esc(emp.last_name)}', ${dId}, ` +
        `'${esc(emp.job_title)}', ${rId}, '${esc(emp.email)}', ` +
        `'${esc(emp.phone)}', '${esc(emp.avatar_seed)}', ${NOW}, ${NOW})`
      )
    })
    lines.push(
      'INSERT INTO employees ' +
      '(id, first_name, last_name, department_id, job_title, region_id, email, phone, avatar_seed, updated_at, created_at) VALUES',
    )
    lines.push(vals.join(',\n') + ';')
    lines.push('')
  }

  lines.push('PRAGMA foreign_keys=ON;')
  return lines.join('\n')
}

// ── Main ──────────────────────────────────────────────────────────────────────

async function main() {
  const seedPath = path.join(__dirname, 'employees-seed.json')
  if (!fs.existsSync(seedPath)) {
    console.error(`❌ Seed file not found: ${seedPath}`)
    console.error('   Run: npx tsx seed/generate.ts')
    process.exit(1)
  }

  console.log('Loading seed data…')
  const { departments, regions, employees } = JSON.parse(
    fs.readFileSync(seedPath, 'utf8'),
  ) as {
    departments: typeof DEPARTMENTS
    regions: typeof REGIONS
    employees: EmployeeSeedRecord[]
  }

  console.log(`  ${departments.length} departments, ${regions.length} regions, ${employees.length.toLocaleString()} employees`)

  const deptIndex: Record<string, number> = {}
  departments.forEach((d, i) => { deptIndex[d.slug] = i + 1 })
  const regionIndex: Record<string, number> = {}
  regions.forEach((r, i) => { regionIndex[r.slug] = i + 1 })

  const tmpDir = path.join(__dirname, '.tmp')
  fs.mkdirSync(tmpDir, { recursive: true })

  try {
    // 1. Departments + regions (also wipes employees first)
    console.log('\n[1/2] Seeding departments & regions…')
    const deptSql = buildDeptRegionSql(departments, regions)
    const deptFile = path.join(tmpDir, 'payload-seed-depts-regions.sql')
    fs.writeFileSync(deptFile, deptSql)
    runSqlFile(deptFile, 'departments + regions')

    // 2. Employees in chunks
    const totalChunks = Math.ceil(employees.length / EMPLOYEES_PER_CHUNK)
    console.log(`\n[2/2] Seeding ${employees.length.toLocaleString()} employees in ${totalChunks} chunks of ${EMPLOYEES_PER_CHUNK.toLocaleString()}…`)

    for (let c = 0; c < totalChunks; c++) {
      const chunk = employees.slice(c * EMPLOYEES_PER_CHUNK, (c + 1) * EMPLOYEES_PER_CHUNK)
      const sql = buildEmployeeChunkSql(chunk, deptIndex, regionIndex, c + 1, totalChunks)
      const chunkFile = path.join(tmpDir, `payload-seed-employees-chunk-${String(c + 1).padStart(2, '0')}.sql`)
      fs.writeFileSync(chunkFile, sql)
      runSqlFile(chunkFile, `employees chunk ${c + 1}/${totalChunks} (#${chunk[0]!.index}–#${chunk[chunk.length-1]!.index})`)
    }

    console.log('\n✓ Payload D1 seed complete.')
    console.log(`  ${departments.length} departments`)
    console.log(`  ${regions.length} regions`)
    console.log(`  ${employees.length.toLocaleString()} employees`)
  } finally {
    // Clean up temp SQL files
    fs.rmSync(tmpDir, { recursive: true, force: true })
  }
}

main().catch(e => { console.error(e); process.exit(1) })
